CREATE TABLE "auth_membership_decisions" (
	"guild_id" text NOT NULL,
	"discord_user_id" text NOT NULL,
	"version" bigint NOT NULL,
	CONSTRAINT "auth_membership_decisions_guild_id_discord_user_id_pk" PRIMARY KEY("guild_id","discord_user_id")
);
--> statement-breakpoint
ALTER TABLE "members" ADD COLUMN "normalized_name" text GENERATED ALWAYS AS (llvy_normalize_search_v1(name)) STORED NOT NULL;--> statement-breakpoint
ALTER TABLE "riot_accounts" ADD COLUMN "normalized_game_name" text GENERATED ALWAYS AS (llvy_normalize_search_v1(game_name)) STORED NOT NULL;--> statement-breakpoint
ALTER TABLE "riot_accounts" ADD COLUMN "normalized_tag_line" text GENERATED ALWAYS AS (llvy_normalize_search_v1(tag_line)) STORED NOT NULL;--> statement-breakpoint
ALTER TABLE "riot_accounts" ADD COLUMN "name_observed_at" timestamp with time zone;--> statement-breakpoint
CREATE INDEX "members_normalized_name_idx" ON "members" USING hash ("normalized_name");--> statement-breakpoint
CREATE INDEX "riot_accounts_normalized_name_idx" ON "riot_accounts" USING hash ("normalized_game_name");
--> statement-breakpoint
INSERT INTO auth_membership_decisions (guild_id, discord_user_id, version)
SELECT guild_id, discord_user_id, membership_version FROM auth_accounts;
--> statement-breakpoint
UPDATE riot_accounts AS account SET name_observed_at = observation.observed_at
FROM (
  SELECT gp.riot_account_id, max(g.played_at::timestamp AT TIME ZONE 'Asia/Seoul') AS observed_at
  FROM game_participants gp JOIN games g ON g.id = gp.game_id
  WHERE g.played_at_source = 'file_mtime'
  GROUP BY gp.riot_account_id
) AS observation WHERE account.id = observation.riot_account_id;
